// @whimtex-effect Samples/Solar Impact
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @group(Burst)
// @param float _Rays = 43 [8 .. 96]
// @param float _Seed = 17 [0 .. ~100]
// @param float _Radius = 0.31 [0.1 .. 0.45]
// @param float _Sharpness = 10 [1 .. 32]
// @endgroup
// @param gradient _Tint = (0, 0, 0, 1) -> (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color) {
 float2 p=uv-.5; float r=length(p); float ang=atan2(p.y,p.x+1e-7);
 float sector=(ang+3.14159265)/6.2831853*_Rays;
 float cell=floor(sector); float rnd=frac(sin(cell*127.1+_Seed*32.7)*43758.5453);
 float ray=pow(saturate(1-abs(frac(sector)-.5)*2),_Sharpness);
 float extent=.18+rnd*.27;
 float streak=ray*(1-smoothstep(extent*.35,extent,r))*smoothstep(.025,.07,r);
 float shock=exp(-abs(r-_Radius)*240.0)*(.55+.45*sin(ang*9.0)*sin(ang*9.0));
 float core=exp(-r*r*900.0);
 float a=saturate(streak+shock+core)*_Opacity;
 return float4(_Tint_Sample(saturate(core+shock*.6+streak*.7)).rgb,a);
}

// @whimtex-effect Samples/Plasma Envelope
// @control(_Opacity)
// @param hidden float _Opacity = 0.48 [0 .. 1]
// @group(Ring)
// @param float _Radius = 0.33 [0.1 .. 0.45]
// @param float _Width = 0.075 [0.01 .. 0.15]
// @param float _Roughness = 0.07 [0 .. 0.1]
// @endgroup
// @param gradient _Tint = (0, 0, 0, 1) -> (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color) {
 float n=saturate(color.r); float d=length(uv-0.5);
 float ridge=abs(d-_Radius+(n-0.5)*_Roughness);
 float body=exp(-pow(ridge/_Width,2.0)*3.0);
 float filament=pow(saturate(n),2.2);
 float a=saturate(body*(0.12+1.7*filament))*_Opacity;
 a*=1-smoothstep(.43,.48,d); a*=smoothstep(.20,.24,d);
 float t=saturate(0.2+filament*1.5+exp(-ridge*220.0)*0.3);
 return float4(_Tint_Sample(t).rgb,a);
}
